// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.function.Supplier;

import org.junit.jupiter.api.Test;

/**
 * The lifecycle peek ({@link PlanLifecycleStore#peekDecision}) against a real {@link PlanLifecycleStore#decision} on an
 * identical twin store, for the STALE branch and the two capacity branches (nothing to evict; an eviction), and the
 * proof that the peek changed nothing in the store it read.
 */
class PlanLifecycleStorePeekTest {

	private static final LogicalLearningKey LOGICAL = LogicalLearningKey.of(
			"difference", "expression", "children", "predicates", "x", "none",
			"bag|duplicate-sensitive|sparql-unbound", "default");
	private static final LogicalLearningKey OTHER_LOGICAL = LogicalLearningKey.of(
			"join", "expression", "children", "predicates", "y", "none",
			"bag|duplicate-sensitive|sparql-unbound", "default");
	private static final LearningApplicability APPLICABILITY = new LearningApplicability(
			1L, 2L, "unconditional", 3L, 4L, 5L);
	private static final PhysicalResidualKey MATERIALIZED = physical("materialized-hash");
	private static final PhysicalResidualKey STREAMING = physical("streaming-correlated");
	private static final PhysicalResidualKey MEMOIZED = physical("memoized-correlated");

	private static final PlanLifecycleStore.ObjectiveEnvelope INCUMBENT = envelope(90.0d, 100.0d, 110.0d);
	/** Its upper bound lies below the incumbent's verified lower bound (90): a decisive challenger. */
	private static final PlanLifecycleStore.ObjectiveEnvelope DECISIVE = envelope(10.0d, 20.0d, 30.0d);
	/** Overlaps the incumbent's verified interval. */
	private static final PlanLifecycleStore.ObjectiveEnvelope OVERLAPPING = envelope(80.0d, 95.0d, 105.0d);
	/** A planned envelope whose upper bound (50) a sibling scan can see. */
	private static final PlanLifecycleStore.ObjectiveEnvelope SIBLING = envelope(40.0d, 45.0d, 50.0d);

	// ---------------------------------------------------------------- STALE

	@Test
	void aStaleEntryPeeksAsTheDecisionAfterItsEpochChangeTransition() {
		// Both entries of the group are STALE and the group cell is gone: the former last good and a challenger.
		Supplier<PlanLifecycleStore> stale = () -> {
			PlanLifecycleStore store = new PlanLifecycleStore(16);
			store.observe(LOGICAL, MATERIALIZED, APPLICABILITY, INCUMBENT, 100.0d, true, Double.POSITIVE_INFINITY,
					1L);
			store.decision(LOGICAL, STREAMING, APPLICABILITY, OVERLAPPING, true);
			store.markAllStale();
			return store;
		};

		assertAll(
				() -> assertEquals("monitoring-only-epoch-change-monitoring",
						stale.get().decision(LOGICAL, STREAMING, APPLICABILITY, OVERLAPPING, false).reason(),
						"COVERAGE_PREREQUISITE: the entry is STALE when decided"),
				() -> assertSameDecision(stale, MATERIALIZED, INCUMBENT, true, "former last good, enforced"),
				() -> assertSameDecision(stale, MATERIALIZED, INCUMBENT, false, "former last good, monitoring"),
				() -> assertSameDecision(stale, STREAMING, OVERLAPPING, true, "challenger, enforced"),
				() -> assertSameDecision(stale, STREAMING, OVERLAPPING, false, "challenger, monitoring"));
	}

	@Test
	void aStaleEntryBesideAVerifiedLastGoodPeeksAsTheDecision() {
		// After the epoch change a sibling is verified again and becomes the group's last good; the challenger stays
		// STALE, so its decision first transitions it to MONITORING and then compares against that last good.
		Supplier<PlanLifecycleStore> staleBesideLastGood = () -> {
			PlanLifecycleStore store = new PlanLifecycleStore(16);
			store.observe(LOGICAL, MATERIALIZED, APPLICABILITY, INCUMBENT, 100.0d, true, Double.POSITIVE_INFINITY,
					1L);
			store.decision(LOGICAL, STREAMING, APPLICABILITY, OVERLAPPING, true);
			store.markAllStale();
			store.observe(LOGICAL, MEMOIZED, APPLICABILITY, INCUMBENT, 100.0d, true, Double.POSITIVE_INFINITY, 2L);
			return store;
		};

		assertAll(
				() -> assertEquals("monitoring-only-epoch-change-monitoring",
						staleBesideLastGood.get()
								.decision(LOGICAL, STREAMING, APPLICABILITY, OVERLAPPING, false)
								.reason(),
						"COVERAGE_PREREQUISITE: the challenger is still STALE"),
				() -> assertEquals(MEMOIZED.digest(),
						staleBesideLastGood.get()
								.decision(LOGICAL, STREAMING, APPLICABILITY, OVERLAPPING, true)
								.lastGoodPhysicalDigest(),
						"COVERAGE_PREREQUISITE: the group has a verified last good"),
				() -> assertSameDecision(staleBesideLastGood, STREAMING, DECISIVE, true, "decisive challenger"),
				() -> assertSameDecision(staleBesideLastGood, STREAMING, OVERLAPPING, true, "overlapping challenger"),
				() -> assertSameDecision(staleBesideLastGood, STREAMING, OVERLAPPING, false, "monitoring"));
	}

	// ---------------------------------------------------------------- capacity

	@Test
	void anAbsentEntryAtCapacityWithNothingToEvictPeeksAsTheCapacityProtectedDecision() {
		// A verified last good and a quarantined entry fill the store; neither may be evicted.
		Supplier<PlanLifecycleStore> full = () -> {
			PlanLifecycleStore store = new PlanLifecycleStore(2);
			store.observe(LOGICAL, MATERIALIZED, APPLICABILITY, INCUMBENT, 100.0d, true, Double.POSITIVE_INFINITY,
					1L);
			store.observe(LOGICAL, STREAMING, APPLICABILITY, INCUMBENT, 1_000.0d, true, 120.0d, 2L);
			return store;
		};

		assertAll(
				() -> assertEquals("monitoring-capacity-protected",
						full.get().decision(LOGICAL, MEMOIZED, APPLICABILITY, OVERLAPPING, true).reason(),
						"COVERAGE_PREREQUISITE: admission finds nothing to evict"),
				() -> assertSameDecision(full, MEMOIZED, OVERLAPPING, true, "enforced"),
				() -> assertSameDecision(full, MEMOIZED, OVERLAPPING, false, "monitoring"));
	}

	@Test
	void anAbsentEntryAtCapacityWhoseAdmissionEvictsAnotherGroupPeeksAsTheDecision() {
		// The other group holds a verified last good and an ordinary MONITORING entry (admitted by a monitoring-only
		// decision, so never transitioned) that admission evicts.
		Supplier<PlanLifecycleStore> evicting = () -> {
			PlanLifecycleStore store = new PlanLifecycleStore(2);
			store.observe(OTHER_LOGICAL, MATERIALIZED, APPLICABILITY, INCUMBENT, 100.0d, true,
					Double.POSITIVE_INFINITY, 1L);
			store.decision(OTHER_LOGICAL, STREAMING, APPLICABILITY, SIBLING, false);
			return store;
		};
		PlanLifecycleStore probe = evicting.get();
		long inputs = probe.decisionInputVersion();
		probe.decision(LOGICAL, MEMOIZED, APPLICABILITY, OVERLAPPING, false);

		assertAll(
				() -> assertEquals(2, probe.size(), "COVERAGE_PREREQUISITE: the store stays at its capacity"),
				() -> assertEquals(inputs + 4L, probe.decisionInputVersion(),
						"COVERAGE_PREREQUISITE: the decision evicted one entry (revision and bookkeeping) and admitted"
								+ " one (revision and bookkeeping)"),
				() -> assertSameDecision(evicting, MEMOIZED, OVERLAPPING, true, "enforced"),
				() -> assertSameDecision(evicting, MEMOIZED, OVERLAPPING, false, "monitoring"));
	}

	@Test
	void anEvictionOfASameGroupSiblingChangesOnlyTheUncomparedRegressionLimit() {
		// The only evictable entry is a sibling in the peeked key's group: the decision evicts it before its sibling
		// scan, the peek still sees it. The regression limit is not a compared lifecycle field.
		Supplier<PlanLifecycleStore> evictingSibling = () -> {
			PlanLifecycleStore store = new PlanLifecycleStore(2);
			store.observe(OTHER_LOGICAL, MATERIALIZED, APPLICABILITY, INCUMBENT, 100.0d, true,
					Double.POSITIVE_INFINITY, 1L);
			store.decision(LOGICAL, STREAMING, APPLICABILITY, SIBLING, true);
			return store;
		};

		for (boolean enforce : new boolean[] { true, false }) {
			PlanLifecycleStore.Decision[] pair = assertComparedFieldsAndPurity(evictingSibling, MEMOIZED, OVERLAPPING,
					enforce, "sibling eviction, enforce=" + enforce);
			PlanLifecycleStore.Decision peek = pair[0];
			PlanLifecycleStore.Decision decision = pair[1];
			assertAll("enforce=" + enforce,
					() -> assertEquals(SIBLING.upper(), peek.regressionLimit(),
							"COVERAGE_PREREQUISITE: the peek's sibling scan sees the entry admission would evict"),
					() -> assertEquals(Double.POSITIVE_INFINITY, decision.regressionLimit(),
							"COVERAGE_PREREQUISITE: the decision evicted that sibling before its scan"),
					() -> assertNotEquals(peek, decision),
					() -> assertEquals(decision, withRegressionLimit(peek, decision.regressionLimit()),
							"every other field, compared or not, is the decision's"));
		}
	}

	// ---------------------------------------------------------------- rule 3': monitoring is observational

	/**
	 * Rule 3' premise: without enforcement, every lifecycle decision and peek is eligible and compares at its envelope
	 * point, bit for bit, whatever the store holds. Random walks over admissions, observations (verified, regressions
	 * into BLOCKED and QUARANTINED, last-good promotions), enforced transitions, leases, epoch changes (STALE), clears
	 * and capacity pressure; after every step every key is peeked and decided without enforcement.
	 */
	@Test
	void withoutEnforcementEveryDecisionAndPeekIsEligibleAtItsEnvelopePoint() {
		List<PhysicalResidualKey> residuals = List.of(MATERIALIZED, STREAMING, MEMOIZED);
		List<LogicalLearningKey> logicals = List.of(LOGICAL, OTHER_LOGICAL);
		long[] coverage = new long[6];
		for (long seed = 1L; seed <= 24L; seed++) {
			Random random = new Random(seed);
			PlanLifecycleStore store = new PlanLifecycleStore(2 + random.nextInt(4));
			List<PlanLifecycleStore.ResolvedEntry> leases = new ArrayList<>();
			for (int step = 0; step < 200; step++) {
				LogicalLearningKey logical = logicals.get(random.nextInt(logicals.size()));
				PhysicalResidualKey residual = residuals.get(random.nextInt(residuals.size()));
				PlanLifecycleStore.ObjectiveEnvelope planned = randomEnvelope(random);
				int choice = random.nextInt(100);
				if (choice < 35) {
					double actual = random.nextBoolean() ? planned.point()
							: planned.upper() * (1.0d + random.nextInt(8));
					double limit = random.nextBoolean() ? Double.POSITIVE_INFINITY : random.nextInt(200);
					store.observe(logical, residual, APPLICABILITY, planned, actual, true, limit, step + 1L);
				} else if (choice < 55) {
					store.decision(logical, residual, APPLICABILITY, planned, true);
				} else if (choice < 70) {
					PlanLifecycleStore.ResolvedEntry lease = store.resolve(logical, residual, APPLICABILITY, planned);
					if (lease != null) {
						leases.add(lease);
					}
				} else if (choice < 85) {
					if (!leases.isEmpty()) {
						store.release(leases.remove(random.nextInt(leases.size())));
					}
				} else if (choice < 95) {
					store.markAllStale();
				} else if (choice < 97) {
					store.clear();
					leases.clear();
				}
				for (LogicalLearningKey key : logicals) {
					for (PhysicalResidualKey physical : residuals) {
						PlanLifecycleStore.ObjectiveEnvelope envelope = randomEnvelope(random);
						PlanLifecycleStore.Decision enforced = store.peekDecision(key, physical, APPLICABILITY,
								envelope,
								true);
						PlanLifecycleStore.Decision peek = store.peekDecision(key, physical, APPLICABILITY, envelope,
								false);
						PlanLifecycleStore.Decision decision = store.decision(key, physical, APPLICABILITY, envelope,
								false);
						String context = "seed " + seed + " step " + step + " " + key.digest() + " "
								+ physical.digest() + " " + envelope;
						assertMonitoringPremise(peek, envelope, "peek, " + context);
						assertMonitoringPremise(decision, envelope, "decision, " + context);
						coverage[0] += enforced.state() == PlanLifecycleStore.State.BLOCKED ? 1 : 0;
						coverage[1] += enforced.state() == PlanLifecycleStore.State.QUARANTINED ? 1 : 0;
						coverage[2] += peek.reason().equals("monitoring-only-epoch-change-monitoring") ? 1 : 0;
						coverage[3] += peek.lastGoodPhysicalDigest().isEmpty() ? 0 : 1;
						coverage[4] += peek.lastGood() ? 1 : 0;
						coverage[5] += peek.reason().equals("monitoring-capacity-protected") ? 1 : 0;
					}
				}
			}
		}
		assertAll(
				() -> assertTrue(coverage[0] > 0L, "COVERAGE_PREREQUISITE: BLOCKED entries"),
				() -> assertTrue(coverage[1] > 0L, "COVERAGE_PREREQUISITE: QUARANTINED entries"),
				() -> assertTrue(coverage[2] > 0L, "COVERAGE_PREREQUISITE: STALE entries"),
				() -> assertTrue(coverage[3] > 0L, "COVERAGE_PREREQUISITE: a last good present"),
				() -> assertTrue(coverage[4] > 0L, "COVERAGE_PREREQUISITE: the decided key is the last good"),
				() -> assertTrue(coverage[5] > 0L, "COVERAGE_PREREQUISITE: capacity-protected answers"));
	}

	private static void assertMonitoringPremise(PlanLifecycleStore.Decision decision,
			PlanLifecycleStore.ObjectiveEnvelope envelope, String context) {
		if (!decision.eligible() || Double.doubleToRawLongBits(decision.comparisonCost()) != Double
				.doubleToRawLongBits(envelope.point())) {
			throw new AssertionError("a monitoring lifecycle answer must be eligible at its envelope point: "
					+ decision + " for " + context);
		}
	}

	private static PlanLifecycleStore.ObjectiveEnvelope randomEnvelope(Random random) {
		double lower = random.nextInt(4) == 0 ? 0.0d : random.nextInt(120) + random.nextDouble();
		double point = lower + (random.nextInt(4) == 0 ? 0.0d : random.nextInt(60) + random.nextDouble());
		double upper = point + (random.nextInt(4) == 0 ? 0.0d : random.nextInt(60) + random.nextDouble());
		return envelope(lower, point, upper);
	}

	// ---------------------------------------------------------------- the peek-input version (review R2)

	@Test
	void thePeekInputVersionMovesWithEveryChangeAPeekCanReadAndNeverWithAPeek() {
		PlanLifecycleStore store = new PlanLifecycleStore(2);
		List<String> unmoved = new ArrayList<>();
		PlanLifecycleStore.ResolvedEntry[] lease = new PlanLifecycleStore.ResolvedEntry[1];
		store.observe(LOGICAL, MATERIALIZED, APPLICABILITY, INCUMBENT, 100.0d, true, Double.POSITIVE_INFINITY, 1L);

		long peeked = store.peekInputVersion();
		store.peekDecision(LOGICAL, MEMOIZED, APPLICABILITY, OVERLAPPING, true);
		long afterPeek = store.peekInputVersion();
		moves(store, "a lease (resolve)", unmoved,
				() -> lease[0] = store.resolve(LOGICAL, STREAMING, APPLICABILITY, SIBLING));
		// The reviewer's case: at capacity, releasing the lease turns the capacity-protected answer of an absent entry
		// into an ordinary one, while the revision and the decision-input version stay where they are.
		long revision = store.revision();
		long inputs = store.decisionInputVersion();
		PlanLifecycleStore.Decision leased = store.peekDecision(LOGICAL, MEMOIZED, APPLICABILITY, OVERLAPPING, true);
		moves(store, "a lease release", unmoved, () -> store.release(lease[0]));
		PlanLifecycleStore.Decision released = store.peekDecision(LOGICAL, MEMOIZED, APPLICABILITY, OVERLAPPING,
				true);
		long revisionAfterRelease = store.revision();
		long inputsAfterRelease = store.decisionInputVersion();
		moves(store, "an admission (with its eviction) by a decision", unmoved,
				() -> store.decision(OTHER_LOGICAL, MEMOIZED, APPLICABILITY, OVERLAPPING, false));
		moves(store, "a planned-envelope overwrite", unmoved,
				() -> store.decision(OTHER_LOGICAL, MEMOIZED, APPLICABILITY, DECISIVE, false));
		moves(store, "an observation", unmoved, () -> store.observe(LOGICAL, MATERIALIZED, APPLICABILITY,
				INCUMBENT, 95.0d, true, Double.POSITIVE_INFINITY, 2L));
		moves(store, "an epoch change", unmoved, store::markAllStale);
		moves(store, "a clear", unmoved, store::clear);
		// An admission alone: free space, a monitoring-only decision (no eviction, no transition, no overwrite).
		PlanLifecycleStore free = new PlanLifecycleStore(16);
		moves(free, "an admission into free space", unmoved,
				() -> free.decision(LOGICAL, MEMOIZED, APPLICABILITY, OVERLAPPING, false));

		assertAll(
				() -> assertEquals(peeked, afterPeek, "a peek changes nothing a peek reads"),
				() -> assertNotEquals(leased.eligible(), released.eligible(),
						"COVERAGE_PREREQUISITE: the release flipped an enforced decision"),
				() -> assertEquals(revision, revisionAfterRelease,
						"COVERAGE_PREREQUISITE: the release moved no revision"),
				() -> assertEquals(inputs, inputsAfterRelease,
						"COVERAGE_PREREQUISITE: nor the decision-input version"),
				() -> assertEquals(List.of(), unmoved, "changes that left the peek-input version unmoved"));
	}

	private static void moves(PlanLifecycleStore store, String change, List<String> unmoved, Runnable mutation) {
		long before = store.peekInputVersion();
		mutation.run();
		if (store.peekInputVersion() == before) {
			unmoved.add(change);
		}
	}

	// ---------------------------------------------------------------- helpers

	/** The peek equals the decision in every field, and the peek changed nothing in the store it read. */
	private static void assertSameDecision(Supplier<PlanLifecycleStore> fixture, PhysicalResidualKey physicalKey,
			PlanLifecycleStore.ObjectiveEnvelope envelope, boolean enforce, String label) {
		PlanLifecycleStore.Decision[] pair = assertComparedFieldsAndPurity(fixture, physicalKey, envelope, enforce,
				label);
		assertEquals(pair[1], pair[0], label + ": every field of the peek is the decision's");
	}

	/**
	 * Peeks on one store and decides on an identical twin built by the same fixture; asserts the compared lifecycle
	 * fields (eligible, last good, comparison cost) and that the peeked store's revision, decision-input version, entry
	 * count, group cells and serialized state are unchanged. Returns {peek, decision}.
	 */
	private static PlanLifecycleStore.Decision[] assertComparedFieldsAndPurity(
			Supplier<PlanLifecycleStore> fixture, PhysicalResidualKey physicalKey,
			PlanLifecycleStore.ObjectiveEnvelope envelope, boolean enforce, String label) {
		PlanLifecycleStore peeked = fixture.get();
		PlanLifecycleStore decided = fixture.get();
		assertArrayEquals(serialized(decided), serialized(peeked), label + ": COVERAGE_PREREQUISITE: identical twins");
		long revision = peeked.revision();
		long inputs = peeked.decisionInputVersion();
		int size = peeked.size();
		int groups = peeked.groupCellCount();
		byte[] state = serialized(peeked);

		PlanLifecycleStore.Decision peek = peeked.peekDecision(LOGICAL, physicalKey, APPLICABILITY, envelope, enforce);
		PlanLifecycleStore.Decision decision = decided.decision(LOGICAL, physicalKey, APPLICABILITY, envelope,
				enforce);

		assertAll(label,
				() -> assertEquals(decision.eligible(), peek.eligible(), "eligible"),
				() -> assertEquals(decision.lastGood(), peek.lastGood(), "lastGood"),
				() -> assertEquals(0, Double.compare(decision.comparisonCost(), peek.comparisonCost()),
						"comparisonCost: decision " + decision.comparisonCost() + ", peek " + peek.comparisonCost()),
				() -> assertEquals(revision, peeked.revision(), "the peek changed the revision"),
				() -> assertEquals(inputs, peeked.decisionInputVersion(), "the peek changed a decision input"),
				() -> assertEquals(size, peeked.size(), "the peek admitted or evicted"),
				() -> assertEquals(groups, peeked.groupCellCount(), "the peek created or removed a group cell"),
				() -> assertArrayEquals(state, serialized(peeked), "the peek changed an entry or a group history"),
				() -> assertTrue(decision.envelope() == envelope && peek.envelope() == envelope));
		return new PlanLifecycleStore.Decision[] { peek, decision };
	}

	private static PlanLifecycleStore.Decision withRegressionLimit(PlanLifecycleStore.Decision decision,
			double regressionLimit) {
		return new PlanLifecycleStore.Decision(decision.state(), decision.eligible(), decision.lastGood(),
				decision.comparisonCost(), decision.envelope(), decision.lastGoodPhysicalDigest(),
				decision.lastGoodVerifiedUpper(), regressionLimit, decision.reason());
	}

	private static byte[] serialized(PlanLifecycleStore store) {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (DataOutputStream output = new DataOutputStream(bytes)) {
			store.writeTo(output);
		} catch (IOException failure) {
			throw new UncheckedIOException(failure);
		}
		return bytes.toByteArray();
	}

	private static PlanLifecycleStore.ObjectiveEnvelope envelope(double lower, double point, double upper) {
		return new PlanLifecycleStore.ObjectiveEnvelope(lower, point, upper);
	}

	private static PhysicalResidualKey physical(String algorithm) {
		return PhysicalResidualKey.of(algorithm, "statement-pattern", "spoc", "per-binding", "none", "none",
				"none", "bound");
	}
}
